<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Ubuntu‑style Desktop</title>
<style>
:root {
  --bg:#1e1e1e; --panel:#2d2d2d; --border:#3c3c3c; --text:#e0e0e0;
  --accent:#e95420; --accent-hover:#f06d3a; --sel:#3a75c4; --sel-text:#fff;
  --font:system-ui,-apple-system,Segoe UI,Ubuntu,Roboto,Helvetica,Arial,sans-serif;
}
*{box-sizing:border-box;margin:0;padding:0}
html,body,#desktop{height:100%;width:100%;overflow:hidden;font-family:var(--font);background:var(--bg);color:var(--text)}
#desktop{position:relative;display:flex;flex-direction:column}

/* Wallpaper */
#wallpaper{position:absolute;inset:0;background:radial-gradient(ellipse at center,#2a2a2a 0%,#141414 100%);z-index:0}

/* Taskbar */
#taskbar{position:relative;z-index:10;height:48px;background:rgba(30,30,30,.95);border-top:1px solid var(--border);
  display:flex;align-items:center;padding:0 12px;gap:8px;user-select:none}
.task-btn{height:36px;padding:0 16px;border:none;background:transparent;color:var(--text);
  border-radius:4px;cursor:pointer;font-size:13px;display:flex;align-items:center;gap:6px;transition:background .15s}
.task-btn:hover{background:var(--panel)} .task-btn:active{background:var(--border)}
.task-btn svg{width:18px;height:18px;fill:currentColor}

/* Window base */
.window{position:absolute;z-index:20;min-width:360px;min-height:240px;background:var(--panel);
  border:1px solid var(--border);border-radius:8px 8px 0 0;overflow:hidden;display:flex;flex-direction:column;
  box-shadow:0 8px 32px rgba(0,0,0,.6);transform:translate(-50%,-50%)}
.win-titlebar{height:36px;background:var(--panel);border-bottom:1px solid var(--border);
  display:flex;align-items:center;padding:0 12px;cursor:grab;user-select:none}
.win-titlebar:active{cursor:grabbing}
.win-title{flex:1;font-size:13px;font-weight:500;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.win-close{width:28px;height:28px;border:none;background:transparent;color:var(--text);border-radius:4px;
  display:flex;align-items:center;justify-content:center;font-size:18px;line-height:1;cursor:pointer;transition:background .15s,color .15s}
.win-close:hover{background:#da2c2c;color:#fff}
.win-content{flex:1;overflow:auto;background:var(--bg);display:flex;flex-direction:column}

/* Files app */
#files-toolbar{height:40px;background:var(--panel);border-bottom:1px solid var(--border);
  display:flex;align-items:center;padding:0 12px;gap:8px}
#files-path{flex:1;font-size:13px;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;padding:4px 8px;background:var(--bg);border:1px solid var(--border);border-radius:4px}
#files-up{padding:0 10px;height:28px;border:1px solid var(--border);background:var(--bg);color:var(--text);border-radius:4px;cursor:pointer;font-size:13px}
#files-up:hover{background:var(--border)}
#files-grid{flex:1;overflow:auto;padding:12px;display:grid;grid-template-columns:repeat(auto-fill,minmax(110px,1fr));gap:12px}
.fs-item{display:flex;flex-direction:column;align-items:center;gap:4px;padding:8px;background:var(--panel);border:1px solid var(--border);border-radius:6px;cursor:pointer;transition:background .15s,border-color .15s;user-select:none}
.fs-item:hover{background:var(--border);border-color:var(--accent)}
.fs-item.selected{background:var(--sel);border-color:var(--sel);color:var(--sel-text)}
.fs-icon{width:32px;height:32px;fill:currentColor;color:#f0c040}
.fs-item.folder .fs-icon{color:#f0c040}
.fs-item.file .fs-icon{color:#8ab4f8}
.fs-name{font-size:12px;text-align:center;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;width:100%}

/* Notepad app */
#notepad-toolbar{height:40px;background:var(--panel);border-bottom:1px solid var(--border);
  display:flex;align-items:center;padding:0 8px;gap:4px}
#tabs{flex:1;display:flex;gap:2px;overflow:auto;padding:4px 0}
.tab{padding:6px 14px;background:var(--bg);border:1px solid var(--border);border-bottom:none;border-radius:6px 6px 0 0;color:var(--text);font-size:13px;cursor:pointer;position:relative;transition:background .15s}
.tab:hover{background:var(--panel)}
.tab.active{background:var(--panel);color:var(--accent);border-color:var(--accent);z-index:1}
.tab-close{margin-left:8px;font-size:16px;line-height:1;opacity:.6;cursor:pointer}
.tab-close:hover{opacity:1;color:var(--accent)}
#new-tab{width:32px;height:32px;border:1px solid var(--border);background:var(--bg);color:var(--text);border-radius:4px;cursor:pointer;font-size:18px;display:flex;align-items:center;justify-content:center;transition:background .15s,color .15s}
#new-tab:hover{background:var(--accent);color:#fff;border-color:var(--accent)}
#editor{flex:1;border:none;background:var(--bg);color:var(--text);font-family:monospace;font-size:14px;line-height:1.5;padding:12px;resize:none;outline:none}
#editor::placeholder{color:#666}

/* Hidden utility */
.hidden{display:none!important}
</style>
</head>
<body>
<div id="desktop">
  <div id="wallpaper"></div>
  <div id="taskbar">
    <button id="open-files" class="task-btn" title="Files">
      <svg viewBox="0 0 24 24"><path d="M10 4H4a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V8a2 2 0 0 0-2-2h-8l-2-2z"/></svg>
      Files
    </button>
    <button id="open-notepad" class="task-btn" title="Notepad">
      <svg viewBox="0 0 24 24"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>
      Notepad
    </button>
  </div>

  <!-- Files Window -->
  <div id="files-window" class="window hidden" style="left:50%;top:50%;width:640px;height:480px">
    <div class="win-titlebar">
      <span class="win-title">Files</span>
      <button class="win-close" data-target="files-window">×</button>
    </div>
    <div class="win-content">
      <div id="files-toolbar">
        <button id="files-up" title="Up">↑ Up</button>
        <div id="files-path">/</div>
      </div>
      <div id="files-grid"></div>
    </div>
  </div>

  <!-- Notepad Window -->
  <div id="notepad-window" class="window hidden" style="left:50%;top:50%;width:640px;height:480px">
    <div class="win-titlebar">
      <span class="win-title">Notepad</span>
      <button class="win-close" data-target="notepad-window">×</button>
    </div>
    <div class="win-content">
      <div id="notepad-toolbar">
        <div id="tabs"></div>
        <button id="new-tab" title="New tab">+</button>
      </div>
      <textarea id="editor" placeholder="Start typing…"></textarea>
    </div>
  </div>
</div>

<script>
// ============ Filesystem Data ============
const fsData = {
  name: '/', type: 'dir', children: {
    bin: {name:'bin',type:'dir',children:{}},
    etc: {name:'etc',type:'dir',children:{}},
    home: {name:'home',type:'dir',children:{
      user: {name:'user',type:'dir',children:{
        Documents: {name:'Documents',type:'dir',children:{}},
        Downloads: {name:'Downloads',type:'dir',children:{}},
        Pictures: {name:'Pictures',type:'dir',children:{}},
        'readme.txt': {name:'readme.txt',type:'file'}
      }}
    }},
    usr: {name:'usr',type:'dir',children:{}},
    var: {name:'var',type:'dir',children:{}}
  }
};

// ============ Window Management ============
function openWindow(id){
  const win=document.getElementById(id);
  win.classList.remove('hidden');
  // center if first open
  if(!win.dataset.positioned){
    win.style.left='50%'; win.style.top='50%';
    win.dataset.positioned='true';
  }
  bringToFront(win);
}
function closeWindow(id){
  document.getElementById(id).classList.add('hidden');
}
function bringToFront(win){
  const windows=document.querySelectorAll('.window:not(.hidden)');
  let maxZ=20;
  windows.forEach(w=>{const z=parseInt(w.style.zIndex)||20; if(z>maxZ) maxZ=z;});
  win.style.zIndex=maxZ+1;
}

// Dragging
let dragWin=null, dragOffsetX=0, dragOffsetY=0;
document.querySelectorAll('.win-titlebar').forEach(tb=>{
  tb.addEventListener('mousedown',e=>{
    if(e.target.classList.contains('win-close')) return;
    dragWin=tb.closest('.window');
    bringToFront(dragWin);
    const rect=dragWin.getBoundingClientRect();
    dragOffsetX=e.clientX-rect.left;
    dragOffsetY=e.clientY-rect.top;
    document.body.style.cursor='grabbing';
    tb.style.cursor='grabbing';
  });
});
document.addEventListener('mousemove',e=>{
  if(!dragWin) return;
  dragWin.style.left=(e.clientX-dragOffsetX)+'px';
  dragWin.style.top=(e.clientY-dragOffsetY)+'px';
  dragWin.style.transform='none';
});
document.addEventListener('mouseup',()=>{
  if(dragWin){dragWin.querySelector('.win-titlebar').style.cursor='grab';}
  dragWin=null; document.body.style.cursor='';
});

// Close buttons
document.querySelectorAll('.win-close').forEach(btn=>{
  btn.addEventListener('click',()=>closeWindow(btn.dataset.target));
});

// Launchers
document.getElementById('open-files').addEventListener('click',()=>{openWindow('files-window'); renderFiles();});
document.getElementById('open-notepad').addEventListener('click',()=>{openWindow('notepad-window'); restoreNotepad();});

// ============ Files App ============
let currentPath='/';
let currentNode=fsData;
const pathEl=document.getElementById('files-path');
const gridEl=document.getElementById('files-grid');
const upBtn=document.getElementById('files-up');

function getNode(path){
  if(path==='/') return fsData;
  const parts=path.split('/').filter(Boolean);
  let node=fsData;
  for(const p of parts){
    if(node.children && node.children[p]) node=node.children[p];
    else return null;
  }
  return node;
}
function renderPath(){
  pathEl.textContent=currentPath;
}
function renderFiles(){
  const node=getNode(currentPath);
  if(!node || node.type!=='dir'){ currentPath='/'; currentNode=fsData; renderFiles(); return; }
  currentNode=node;
  renderPath();
  gridEl.innerHTML='';
  const entries=Object.values(node.children || {}).sort((a,b)=>{
    if(a.type!==b.type) return a.type==='dir'?-1:1;
    return a.name.localeCompare(b.name);
  });
  entries.forEach(entry=>{
    const el=document.createElement('div');
    el.className='fs-item '+(entry.type==='dir'?'folder':'file');
    el.dataset.name=entry.name;
    el.dataset.type=entry.type;
    el.innerHTML=`
      <svg class="fs-icon" viewBox="0 0 24 24" aria-hidden="true">
        ${entry.type==='dir'?
          '<path d="M10 4H4a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V8a2 2 0 0 0-2-2h-8l-2-2z"/>':
          '<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/>'}
      </svg>
      <span class="fs-name">${entry.name}</span>
    `;
    // double-click to navigate folder
    el.addEventListener('dblclick',()=>{
      if(entry.type==='dir'){
        currentPath=currentPath==='/'?'/'+entry.name:currentPath+'/'+entry.name;
        renderFiles();
      }
    });
    gridEl.appendChild(el);
  });
}
upBtn.addEventListener('click',()=>{
  if(currentPath==='/') return;
  const parts=currentPath.split('/').filter(Boolean);
  parts.pop();
  currentPath=parts.length?'/'+parts.join('/'):'/';
  renderFiles();
});
// initial
renderFiles();

// ============ Notepad App ============
const STORAGE_KEY='desktop_notepad_tabs';
let tabs=[]; // {id, title, content}
let activeTabId=null;
const tabsEl=document.getElementById('tabs');
const editorEl=document.getElementById('editor');
const newTabBtn=document.getElementById('new-tab');

function saveTabs(){
  localStorage.setItem(STORAGE_KEY,JSON.stringify({tabs,activeTabId}));
}
function loadTabs(){
  try{
    const data=JSON.parse(localStorage.getItem(STORAGE_KEY)||'{}');
    tabs=data.tabs||[];
    activeTabId=data.activeTabId||null;
  }catch(e){tabs=[];activeTabId=null;}
}
function generateId(){return 'tab_'+Date.now()+'_'+Math.random().toString(36).substr(2,5);}
function createTab(content=''){
  const id=generateId();
  const tab={id,title:'Untitled',content};
  tabs.push(tab);
  return tab;
}
function renderTabs(){
  tabsEl.innerHTML='';
  tabs.forEach(tab=>{
    const btn=document.createElement('button');
    btn.className='tab '+(tab.id===activeTabId?'active':'');
    btn.dataset.id=tab.id;
    btn.innerHTML=`${tab.title}<span class="tab-close">×</span>`;
    btn.addEventListener('click',e=>{
      if(e.target.classList.contains('tab-close')){
        e.stopPropagation();
        closeTab(tab.id);
      }else{
        switchTab(tab.id);
      }
    });
    tabsEl.appendChild(btn);
  });
}
function switchTab(id){
  // save current editor content to active tab
  if(activeTabId){
    const cur=tabs.find(t=>t.id===activeTabId);
    if(cur) cur.content=editorEl.value;
  }
  activeTabId=id;
  const tab=tabs.find(t=>t.id===id);
  if(tab){
    editorEl.value=tab.content;
    editorEl.focus();
  }
  renderTabs();
  saveTabs();
}
function closeTab(id){
  const idx=tabs.findIndex(t=>t.id===id);
  if(idx===-1) return;
  tabs.splice(idx,1);
  if(activeTabId===id){
    activeTabId=tabs[idx]?tabs[idx].id: (tabs[idx-1]?tabs[idx-1].id:null);
  }
  if(activeTabId){
    const tab=tabs.find(t=>t.id===activeTabId);
    editorEl.value=tab?tab.content:'';
  }else{
    editorEl.value='';
  }
  renderTabs();
  saveTabs();
}
newTabBtn.addEventListener('click',()=>{
  const tab=createTab('');
  switchTab(tab.id);
});
editorEl.addEventListener('input',()=>{
  if(activeTabId){
    const tab=tabs.find(t=>t.id===activeTabId);
    if(tab) tab.content=editorEl.value;
  }
  // debounce save
  clearTimeout(editorEl._saveTimer);
  editorEl._saveTimer=setTimeout(saveTabs,500);
});
function restoreNotepad(){
  loadTabs();
  if(tabs.length===0){
    const tab=createTab('');
    activeTabId=tab.id;
  }else if(!tabs.find(t=>t.id===activeTabId)){
    activeTabId=tabs[0].id;
  }
  renderTabs();
  switchTab(activeTabId);
}

// Initialize notepad on first open (but restoreNotepad called on open)
// Also restore on page load for persistence across reloads
restoreNotepad();
</script>
</body>
</html>
